import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
  type CarouselApi,
} from "@/components/ui/carousel";
import {
  Target,
  MessageSquare,
  Presentation,
  FileText,
  Users,
  Sparkles,
  ArrowRight,
  CheckCircle,
  LucideIcon,
  Lightbulb,
  Code,
  TrendingUp,
  ChevronRight,
  Shield,
  Calendar,
} from "lucide-react";
import { SiWhatsapp } from "react-icons/si";
import servicesData from "@/data/services.json";
import { SectionShareButtons } from "@/components/SocialShare";
import Autoplay from "embla-carousel-autoplay";
import { useRef, useState, useEffect } from "react";

const iconMap: Record<string, LucideIcon> = {
  Target,
  MessageSquare,
  Presentation,
  FileText,
  Users,
  Sparkles,
  Lightbulb,
  Code,
  TrendingUp,
};

interface Service {
  id: string;
  title: string;
  description: string;
  icon: string;
  features: string[];
  popular: boolean;
}

interface CaseStudy {
  id: string;
  icon: string;
  gradientFrom: string;
  gradientTo: string;
  before: {
    title: string;
    subtitle: string;
    details: string;
  };
  coaching: {
    sessions: number;
    focus: string[];
    approach: string;
  };
  after: {
    title: string;
    highlight: string;
    details: string;
  };
}

export default function ServicesSection() {
  const { sectionBadge, sectionTitle, sectionTitleHighlight, sectionDescription, services, ctaButtons, caseStudies, caseStudyShowcase, popularBadgeText } = servicesData;
  const [api, setApi] = useState<CarouselApi>();
  const [currentIndex, setCurrentIndex] = useState(0);

  const autoplayPlugin = useRef(
    Autoplay({ delay: 5000, stopOnInteraction: false, stopOnMouseEnter: true })
  );

  useEffect(() => {
    if (!api) return;

    const onSelect = () => {
      setCurrentIndex(api.selectedScrollSnap());
    };

    api.on("select", onSelect);
    onSelect();

    return () => {
      api.off("select", onSelect);
    };
  }, [api]);

  const studies = caseStudies as CaseStudy[];

  return (
    <section
      id="services"
      className="py-10 md:py-14 gradient-services relative"
      data-testid="section-services"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <Badge variant="secondary" className="mb-4">{sectionBadge}</Badge>
          <h2
            className="text-3xl md:text-4xl font-bold mb-4"
            data-testid="text-services-title"
          >
            {sectionTitle} <span className="text-primary">{sectionTitleHighlight}</span>
          </h2>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            {sectionDescription}
          </p>
        </div>

        <div className="mb-12" data-testid="card-case-studies">
          <div className="flex items-center justify-between mb-6">
            <div>
              <Badge variant="secondary" className="mb-2">{caseStudyShowcase.badge}</Badge>
              <h3 className="text-2xl font-bold">{caseStudyShowcase.title}</h3>
            </div>
            <div className="hidden md:flex items-center gap-2 text-sm text-muted-foreground">
              <Shield className="w-4 h-4" />
              <span>{caseStudyShowcase.privacyNote}</span>
            </div>
          </div>

          <Carousel
            opts={{ align: "start", loop: true }}
            plugins={[autoplayPlugin.current]}
            className="w-full"
            setApi={setApi}
            onMouseEnter={() => autoplayPlugin.current.stop()}
            onMouseLeave={() => autoplayPlugin.current.play()}
          >
            <CarouselContent className="-ml-4">
              {studies.map((study) => {
                const IconComponent = iconMap[study.icon] || TrendingUp;
                return (
