                  <DialogContent className="sm:max-w-md">
                    <DialogHeader>
                      <DialogTitle>Register for {webinar.title}</DialogTitle>
                      <DialogDescription>
                        Get notified when this webinar is scheduled. It's free!
                      </DialogDescription>
                    </DialogHeader>
                    <RegistrationForm 
