// GitHub deployment script using Octokit
import { Octokit } from '@octokit/rest';
import * as fs from 'fs';
import * as path from 'path';

let connectionSettings: any;

async function getAccessToken() {
  if (connectionSettings && connectionSettings.settings.expires_at && new Date(connectionSettings.settings.expires_at).getTime() > Date.now()) {
    return connectionSettings.settings.access_token;
  }

  const hostname = process.env.REPLIT_CONNECTORS_HOSTNAME;
  const xReplitToken = process.env.REPL_IDENTITY 
    ? 'repl ' + process.env.REPL_IDENTITY 
    : process.env.WEB_REPL_RENEWAL 
    ? 'depl ' + process.env.WEB_REPL_RENEWAL 
    : null;

  if (!xReplitToken) {
    throw new Error('X_REPLIT_TOKEN not found for repl/depl');
  }

  connectionSettings = await fetch(
    'https://' + hostname + '/api/v2/connection?include_secrets=true&connector_names=github',
    {
      headers: {
        'Accept': 'application/json',
        'X_REPLIT_TOKEN': xReplitToken
      }
    }
  ).then(res => res.json()).then(data => data.items?.[0]);

  const accessToken = connectionSettings?.settings?.access_token || connectionSettings.settings?.oauth?.credentials?.access_token;

  if (!connectionSettings || !accessToken) {
    throw new Error('GitHub not connected');
  }
  return accessToken;
}

async function getGitHubClient() {
  const accessToken = await getAccessToken();
  return new Octokit({ auth: accessToken });
}

async function getAllFiles(dir: string, baseDir: string = dir): Promise<{path: string, content: string, isBinary: boolean}[]> {
  const files: {path: string, content: string, isBinary: boolean}[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(baseDir, fullPath);

    if (entry.isDirectory()) {
      const subFiles = await getAllFiles(fullPath, baseDir);
      files.push(...subFiles);
    } else {
      // Only images are truly binary - read as base64
      // Text files (html, css, js, md, etc) - read as utf8
      const isBinary = /\.(png|jpg|jpeg|gif|ico|woff|woff2|ttf|eot|webp)$/i.test(entry.name);
      const content = fs.readFileSync(fullPath, isBinary ? 'base64' : 'utf8');
      files.push({ path: relativePath, content, isBinary });
    }
  }

  return files;
}

async function deployToGitHub() {
  const owner = 'FullStackMaster1';
  const repo = 'fullstackmaster1.github.io';
  const branch = 'main';
  const docsDir = './docs';
  const rootDir = './github-root';

  console.log('🚀 Starting GitHub deployment...');
  console.log(`📁 Repository: ${owner}/${repo}`);

  try {
    const octokit = await getGitHubClient();
    console.log('✅ GitHub client authenticated');

    // Get the current commit SHA
    const { data: refData } = await octokit.git.getRef({
      owner,
      repo,
      ref: `heads/${branch}`
    });
    const currentCommitSha = refData.object.sha;
    console.log(`📌 Current commit: ${currentCommitSha.substring(0, 7)}`);

    // Get the current tree
    const { data: commitData } = await octokit.git.getCommit({
      owner,
      repo,
      commit_sha: currentCommitSha
    });

    // Get all files from docs directory
    const files = await getAllFiles(docsDir);

    // Get root files (README.md, CNAME)
    const rootFiles = await getAllFiles(rootDir);

    console.log(`📄 Found ${files.length} docs files + ${rootFiles.length} root files to upload`);

    // Create blobs for each file
    const blobs: {path: string, sha: string, mode: string, type: string}[] = [];

    // Add root files first (README.md, CNAME at repo root)
    for (const file of rootFiles) {
      const { data: blobData } = await octokit.git.createBlob({
        owner,
        repo,
        content: file.isBinary ? file.content : Buffer.from(file.content).toString('base64'),
        encoding: 'base64'
      });

      blobs.push({
        path: file.path,
        sha: blobData.sha,
        mode: '100644',
        type: 'blob'
      });
      console.log(`  ✓ ${file.path} (root)`);
    }

    // Add docs files
    for (const file of files) {
      // Binary files are already base64 encoded when read
      // Text files need to be converted to base64 for the API
      const { data: blobData } = await octokit.git.createBlob({
        owner,
        repo,
        content: file.isBinary ? file.content : Buffer.from(file.content).toString('base64'),
        encoding: 'base64'
      });

      // Push to docs/ folder in the repository
      blobs.push({
        path: `docs/${file.path}`,
        sha: blobData.sha,
        mode: '100644',
        type: 'blob'
      });
      console.log(`  ✓ docs/${file.path}`);
    }

    // Create a new tree - use base_tree to preserve other files in repo
    const { data: treeData } = await octokit.git.createTree({
      owner,
      repo,
      tree: blobs as any,
      base_tree: commitData.tree.sha // Preserve existing files, only update docs/
    });
    console.log(`🌳 Created new tree: ${treeData.sha.substring(0, 7)}`);

    // Create a new commit
    const { data: newCommit } = await octokit.git.createCommit({
      owner,
      repo,
      message: 'Updated site with GA tracking, email templates, and branding',
      tree: treeData.sha,
      parents: [currentCommitSha]
    });
    console.log(`💾 Created commit: ${newCommit.sha.substring(0, 7)}`);

    // Update the reference
    await octokit.git.updateRef({
      owner,
      repo,
      ref: `heads/${branch}`,
      sha: newCommit.sha
    });

    console.log('');
    console.log('🎉 Deployment successful!');
    console.log(`🔗 Your site will be live at: https://fullstackmaster1.github.io`);
    console.log(`🔗 Custom domain: https://www.fullstackmaster.net`);
    console.log('');
    console.log('⏱️  GitHub Pages may take 2-3 minutes to rebuild.');

  } catch (error: any) {
    console.error('❌ Deployment failed:', error.message);
    if (error.response) {
      console.error('API Response:', error.response.data);
    }
    process.exit(1);
  }
}

deployToGitHub();

